    m, n = len(grid1), len(grid1[0])
    if not grid1:
        return grid2 == []
    # Build rotations of grid1
    rotateds = []
    # 0 degrees: the original grid
    rotateds.append([row[:] for row in grid1])
    # 90 degrees: rotate around top-left
    for col in range(n):
        rotated = []
        for row in range(m):
            rotated.append(grid1[m - 1 - row][col])
        rotateds.append(rotated)
    # 180 degrees: rotate twice 90, only keep the second
    rotated = []
    for row in reversed(grid1):
