    def rotate(grid, h, w, rotation):
        rot = rotation % 4
        if rot == 1:
            r = [[grid[w - j - 1][i] for j in range(h)] for i in range(w)]
        elif rot == 2:
            r = [[grid[h - i - 1][w - j - 1] for j in range(w)] for i in range(h)]
