def count_paths(grid):
    # If start or end is blocked, no path exists
    if grid[0][0] or grid[-1][-1]:
        return 0
    m, n = len(grid), len(grid[0])
    # dp[i][j] = number of paths to (i,j) without stepping into obstacles
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # One way to start at the top-left
    # Fill in the first row and first column, skipping obstacles
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            break
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            break
    # Fill in the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0
    return dp[-1][-1]
```

