def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty or single-cell board is valid

    first = grid[0][0]
    second = grid[0][1]
    if first == second:
        return False

    expected = first
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i + j) % 2 == 0:
                expected = first
            else:
                expected = second
            if grid[i][j] != expected:
                return False
    return True
