def increment_semver(version, part):
    """Increment the part of a semantic version string and return the new version."""
    if part not in ('major', 'minor', 'patch'):
        raise ValueError('part must be one of "major", "minor", or "patch"')
    major, minor, patch = map(int, version.split('.'))
    if part == 'patch':
        return f'{major}.{minor}.{patch + 1}'
    elif part == 'minor':
        return f'{major}.{minor + 1}.0'
    elif part == 'major':
        return f'{major + 1}.0.0'
    else:
        raise RuntimeError('Unreachable')  # one of the three paths must have run
```

