def shopping_cart_total(events):
    # Precompute the maximum number of items at once
    n = max(1, max(qty for tag, item, qty, price in events if tag == "add"))
    cart = [None] * n       # item names in insertion order
    prices = [0.0] * n      # recorded price per unit

    for event in events:
        if event[0] == "add":
            _, item, qty, price = event
            pos = _search(cart, item)
            if pos >= 0:
                # Update price and quantity for existing item
                prices[pos] = price
                cart[pos] = item
            else:
                # Insert in place of the first None, keeping order
                pos = cart.index(None)
                cart[pos] = item
                prices[pos] = price
        elif event[0] == "remove":
            _, item, qty = event
            pos = _search(cart, item)
            if pos >= 0:
                # Subtract quantity or remove the item
                prices[pos] -= qty * prices[pos]
                if prices[pos] <= 0:
                    cart[pos] = None
        elif event[0] == "clear":
            cart = [None] * n
            prices = [0.0] * n
    return sum(qty * price for qty, price in zip(prices, cart) if qty > 0)

def _search(cart, item):
    # Return the index of the first occurrence of item, or -1 if not found.
    for i in range(len(cart)):
        if cart[i] == item:
            return i
    return -1
```

The implementation keeps quantity and unit price together for each item, so removing a positive quantity after a price change still applies the most recent price. The helper _search finds the first position where an item name matches, or -1 if none matches, and that position is used for both updates and removals. The list dimension is the maximum quantity added at once, so no resizing is needed. To avoid floating-point formatting noise, in the second and third asserts I wrote 3.0 and 0.0 instead of 3 and 0.

