def coffee_machine_credit(events, prices, stock):
    remaining = stock.copy()
    credit = 0
    total = 0
    for kind, value in events:
        if kind == "insert":
            credit += value
        elif kind == "select":
            count = remaining.get(value, 0)
            if count > 0 and credit >= prices[value]:
                remaining[value] = count - 1
                credit -= prices[value]
                total += 1
            else:
                pass  # The spec says ignored selections leave the credit and stock unchanged
    return (credit, remaining, total)
```

